sp_widget.client_script:
api.controller = function($timeout) {
  var c = this;
  if (c.data.allowed && c.data.targetPage) {
    $timeout(function() {
      window.location.href = '?id=' + c.data.targetPage;
    }, 400);
  }
};

sp_widget.css:
.wei-redirect-wrapper {
  min-height: 100vh;
  background-color: #F8FAFC;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  display: flex;
  flex-direction: column;
}
.wei-redirect-header {
  background: #FFFFFF;
  border-bottom: 1px solid #E2E8F0;
  padding: 16px 32px;
}
.wei-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}
.wei-brand-title {
  font-size: 16px;
  font-weight: 700;
  color: #1E293B;
}
.wei-redirect-body {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
}
.wei-redirect-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
  max-width: 500px;
  width: 100%;
  padding: 48px 36px;
  text-align: center;
}
.wei-spinner {
  width: 48px;
  height: 48px;
  border: 4px solid #E2E8F0;
  border-top-color: #1976D2;
  border-radius: 50%;
  animation: wei-spin 0.9s linear infinite;
  margin: 0 auto 24px;
}
@keyframes wei-spin {
  to { transform: rotate(360deg); }
}
.wei-redirect-title {
  font-size: 20px;
  font-weight: 700;
  color: #0F172A;
  margin: 0 0 10px;
}
.wei-redirect-desc {
  font-size: 14px;
  color: #64748B;
  margin: 0 0 20px;
  line-height: 1.5;
}
.wei-denied-icon {
  font-size: 42px;
  color: #EF4444;
  margin-bottom: 16px;
}
.text-danger {
  color: #EF4444 !important;
}
.wei-fallback-actions {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid #F1F5F9;
}

sp_widget.script:
(function() {
  var roleParam = ($sp.getParameter('role') || '').toLowerCase().trim();
  data.userName = gs.getUserDisplayName() || 'User';
  data.allowed = false;
  data.targetPage = '';
  data.requestedRole = roleParam;

  var roleTitles = {
    'staff': 'Warehouse Staff',
    'technician': 'Technician',
    'supervisor': 'Supervisor'
  };
  data.requestedRoleTitle = roleTitles[roleParam] || roleParam;

  // Determine user's roles
  var isSup = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
  var isTech = gs.hasRole('x_1956908_wareho_0.technician');
  var isStaff = gs.hasRole('x_1956908_wareho_0.staff');

  // Verify requested role specifically (Never choose dashboard by role priority alone!)
  if (roleParam === 'staff') {
    if (isStaff || isSup) {
      data.allowed = true;
      data.targetPage = 'x_1956908_wareho_0_staff_dashboard';
    }
  } else if (roleParam === 'technician') {
    if (isTech || isSup) {
      data.allowed = true;
      data.targetPage = 'x_1956908_wareho_0_tech_dashboard';
    }
  } else if (roleParam === 'supervisor') {
    if (isSup) {
      data.allowed = true;
      data.targetPage = 'x_1956908_wareho_0_sup_dashboard';
    }
  }

  // If not allowed, compute the highest dashboard the user may use
  if (!data.allowed) {
    if (isSup) {
      data.highestAllowedPage = 'x_1956908_wareho_0_sup_dashboard';
      data.highestAllowedTitle = 'Supervisor Dashboard';
    } else if (isTech) {
      data.highestAllowedPage = 'x_1956908_wareho_0_tech_dashboard';
      data.highestAllowedTitle = 'Technician Dashboard';
    } else if (isStaff) {
      data.highestAllowedPage = 'x_1956908_wareho_0_staff_dashboard';
      data.highestAllowedTitle = 'Staff Dashboard';
    } else {
      data.highestAllowedPage = '';
      data.highestAllowedTitle = '';
    }
  }
})();
